#include <WiFi.h>
#include <WebServer.h>
#include <Wire.h>
#include <tda7419.hpp>

// --- НАСТРОЙКИ WI-FI ---
const char* ssid = "SityServis";       // <-- ВПИШИ ИМЯ СВОЕЙ СЕТИ
const char* password = "1234567890"; // <-- ВПИШИ ПАРОЛЬ

// --- I2C и TDA7419 ---
#define SDA_PIN 23
#define SCL_PIN 19
#define TDA_ADDR 0x44               // 7-битный адрес TDA7419 (обычно 0x88 -> 0x44)

WebServer server(80);

// Создаём объект TDA7419 с явным указанием Wire и адреса
TDA7419::TDA7419 tda(&Wire, TDA_ADDR);

// Глобальные переменные для хранения текущих настроек
int8_t masterVolume = -15;          // -79..+15 дБ
uint8_t inputSource = 3;            // SE1=1, SE2=2, SE3=3
int8_t bassLevel = 0;                // -15..+15 дБ
int8_t midLevel = 0;                 // -15..+15 дБ
int8_t trebleLevel = 0;              // -15..+15 дБ
bool loudness = false;
bool muteState = false;              // false = звук есть, true = Mute

// Дополнительные «срезы» (фильтры) — можно менять под себя
// Частоты и Q для эквалайзера (по умолчанию средние значения)
const uint8_t BASS_FREQ = 80;        // Гц (60/80/100/200)
const float BASS_Q = 1.25;           // Q (1.0/1.25/1.5/2.0)

const uint8_t MID_FREQ = 1000;       // Гц (500/1000/1500/2500)
const float MID_Q = 1.0;             // Q (0.5/0.75/1.0/1.25)

const uint8_t TREBLE_FREQ = 12500;   // Гц (10k/12.5k/15k/17.5k)

// HTML-страница (веб-интерфейс)
const char index_html[] PROGMEM = R"rawliteral(
