void setup() {
 Serial.begin(115200);
 Serial.println("TDA7419 Full Control Start");

 // Инициализация I2C
 Wire.begin(SDA_PIN, SCL_PIN);

 // Проверка I2C (скан)
 Serial.print("Scanning I2C... ");
 byte count = 0;
 for (int addr = 1; addr < 127; addr++) {
   Wire.beginTransmission(addr);
   if (Wire.endTransmission() == 0) {
     Serial.print("Found: 0x");
     Serial.println(addr, HEX);
     count++;
   }
 }
 if (count == 0) {
   Serial.println("No I2C devices found!");
 } else {
   Serial.println("Scan complete.");
 }

 // Инициализация TDA7419 через библиотеку
 if (!tda.begin()) {
   Serial.println("TDA7419 init failed!");
   while (1) delay(1000);
 }
 Serial.println("TDA7419 initialized via library.");

 // Установка «срезов» (частот и Q) — это и есть те самые «фильтры/срезы»
 tda.setBassFrequency(BASS_FREQ);
 tda.setBassQ(BASS_Q);

 tda.setMiddleFrequency(MID_FREQ);
 tda.setMiddleQ(MID_Q);

 tda.setTrebleFrequency(TREBLE_FREQ);

 // Начальные значения
 tda.setMasterVolume(masterVolume);
 tda.setMainSource((TDA7419::InputSource)inputSource);
 tda.setBassLevel(bassLevel);
 tda.setMiddleLevel(midLevel);
 tda.setTrebleLevel(trebleLevel);
 tda.setLoudness(loudness);
 tda.setMute(muteState);

 Serial.println("Initial settings applied.");

 // Wi-Fi
 WiFi.begin(ssid, password);
 Serial.print("Connecting to WiFi");
 while (WiFi.status() != WL_CONNECTED) {
   delay(500);
   Serial.print(".");
 }
 Serial.println();
 Serial.print("IP address: ");
 Serial.println(WiFi.localIP());

 server.on("/", handleRoot);
 server.on("/set", handleSet);
 server.begin();
 Serial.println("HTTP server started.");
}

void loop() {
 server.handleClient();
}

void handleRoot() {
 server.send(200, "text/html", index_html);
}

void handleSet() {
 Serial.println("--- POST /set received ---");

 if (server.hasArg("masterVolume")) {
   masterVolume = server.arg("masterVolume").toInt();
   tda.setMasterVolume(masterVolume);
   Serial.print("Master Volume set to: ");
   Serial.println(masterVolume);
 }

 if (server.hasArg("inputSource")) {
   String src = server.arg("inputSource");
   uint8_t newSrc = src.toInt();
   if (newSrc >= 1 && newSrc <= 3) {
     inputSource = newSrc;
     tda.setMainSource((TDA7419::InputSource)inputSource);
     Serial.print("Input Source set to SE");
     Serial.println(inputSource);
   }
 }

 if (server.hasArg("bassLevel")) {
   bassLevel = server.arg("bassLevel").toInt();
   tda.setBassLevel(bassLevel);
   Serial.print("Bass Level set to: ");
   Serial.println(bassLevel);
 }

 if (server.hasArg("middleLevel")) {
   midLevel = server.arg("middleLevel").toInt();
   tda.setMiddleLevel(midLevel);
   Serial.print("Middle Level set to: ");
   Serial.println(midLevel);
 }

 if (server.hasArg("trebleLevel")) {
   trebleLevel = server.arg("trebleLevel").toInt();
   tda.setTrebleLevel(trebleLevel);
   Serial.print("Treble Level set to: ");
   Serial.println(trebleLevel);
 }

 if (server.hasArg("loudness")) {
   loudness = (server.arg("loudness") == "on");
   tda.setLoudness(loudness);
   Serial.print("Loudness set to: ");
   Serial.println(loudness ? "ON" : "OFF");
 }

 if (server.hasArg("mute")) {
   muteState = (server.arg("mute") == "on");
   tda.setMute(muteState);
   Serial.print("Mute set to: ");
   Serial.println(muteState ? "ON" : "OFF");
 }

 server.sendHeader("Location", "/");
 server.send(303);
}
